{

    internal InnerPrefetchScheduleTrafficShapingRetrievalWindowFactory TrafficShapingRetrievalWindowFactory { get; set; }

    internal InnerPrefetchScheduleTrafficShapingTpsConfigurationFactory TrafficShapingTpsConfigurationFactory { get; set; }

    protected override Humidifier.MediaTailor.PrefetchScheduleTypes.PrefetchRetrieval Create()
    {
        var prefetchRetrievalResult = CreatePrefetchRetrieval();
        factoryAction?.Invoke(prefetchRetrievalResult);

        return prefetchRetrievalResult;
    }

    private Humidifier.MediaTailor.PrefetchScheduleTypes.PrefetchRetrieval CreatePrefetchRetrieval()
    {
        var prefetchRetrievalResult = new Humidifier.MediaTailor.PrefetchScheduleTypes.PrefetchRetrieval();

        return prefetchRetrievalResult;
    }
    public override void CreateChildren(Humidifier.MediaTailor.PrefetchScheduleTypes.PrefetchRetrieval result)
    {
        base.CreateChildren(result);

        result.TrafficShapingRetrievalWindow ??= TrafficShapingRetrievalWindowFactory?.Build();
        result.TrafficShapingTpsConfiguration ??= TrafficShapingTpsConfigurationFactory?.Build();
    }

} // End Of Class

